def dump_yaml(data, indent=0):
    lines = []
    ind = "  " * indent
    if isinstance(data, dict):
        for k, v in data.items():
            if isinstance(v, (dict, list)):
                lines.append(f"{ind}{k}:")
                lines.append(dump_yaml(v, indent + 1))
            elif v is None:
                lines.append(f"{ind}{k}: null")
            elif isinstance(v, bool):
                lines.append(f"{ind}{k}: {'true' if v else 'false'}")
            elif isinstance(v, (int, float)):
                lines.append(f"{ind}{k}: {v}")
            else:
                s = str(v).replace('"', '\\"')
                lines.append(f'{ind}{k}: "{s}"')
    elif isinstance(data, list):
        for item in data:
            if isinstance(item, (dict, list)):
                lines.append(f"{ind}-")
                lines.append(dump_yaml(item, indent + 1))
            elif item is None:
                lines.append(f"{ind}- null")
            elif isinstance(item, bool):
                lines.append(f"{ind}- {'true' if item else 'false'}")
            elif isinstance(item, (int, float)):
                lines.append(f"{ind}- {item}")
            else:
                s = str(item).replace('"', '\\"')
                lines.append(f'{ind}- "{s}"')
    return "\n".join(lines)

